def G(t):
    R=[("ChatGPT","Чат Джі-Пі-Ті"),("Gemini Notebook","Джеміні Ноутбук"),("NotebookLM","Ноутбук Ел-Ем"),("Google Translate","Гугл Транслейт"),("AI Mode","Ей-Ай Мод"),
       ("Lens","Ленз"),("Gemini","Джеміні"),("Google","Гугл"),("Claude","Клод"),("Skills","скіли"),("Live translate","Лайв транслейт"),("LIGA360","Ліга триста шістдесят"),
       ("Opendatabot","Опендатабот"),("ЄДРСР","реєстр судових рішень"),("Word","Ворд"),("YouTube","Ютуб"),("PDF","Пі-Ді-Еф"),("МОЗ","Міністерство охорони здоров'я"),
       ("Viber","Вайбер"),("№ 240/14153/24",""),("ВКДКА","дисциплінарна комісія адвокатури")]
    for a,b in R: t=t.replace(a,b)
    t=re.sub(r"ШІ-(\w+)", r"\1 штучного інтелекту", t)
    for a,b in [("від ШІ","від штучного інтелекту"),("з ШІ","зі штучним інтелектом"),("ШІ не","штучний інтелект не"),("у ШІ","у штучний інтелект")]: t=t.replace(a,b)
    return t.replace("ШІ","штучний інтелект")

